1	// Module customer-action, key: the order id. Owns R3.1, R3.2, S1 (DECOMPOSITION 4.4).
2	// Started when the order is recorded and has an unavailable fulfilment; its clock runs from placedAt (S1).
3	// An amend or cancel counts while it is at or before D = placedAt + customerActionHours; the timeout is at D + 1 min,
4	// so it is strictly after D. A customer action before clearance is judged here too (R3.2 says nothing against it).
5	
6	const MIN = 60000;
7	
8	export function step(input, ctx) {
9	  const s = ctx.state ?? { st: 'idle', D: null, placedAt: null, clearedAt: null, at: null, reason: null, advanced: false, fs: [] };
10	  let obligations;
11	  if (input.op === 'start') {
12	    s.placedAt = input.placedAt;
13	    s.fs = input.fulfilments.map(f => ({ fulfilmentId: f.fulfilmentId, available: f.available }));
14	    const hours = Number(deep(J(ctx.files, `rulebook/${input.edition}/policy.json`), 'customerActionHours'));
15	    s.D = plusMin(input.placedAt, hours * 60);
16	    s.st = 'pending';
17	    if (input.resumed) s.advanced = true;
18	    obligations = { upsert: [wake(s)] };
19	  } else if (input.op === 'cleared') {
20	    if (s.st === 'pending') {
21	      s.st = 'waiting';
22	      s.clearedAt = input.at;
23	    } else if (s.st === 'overdue') {
24	      s.clearedAt = input.at;
25	      advance(s, ctx);
26	      timeout(s, ctx, input.at);
27	    }
28	  } else if (input.op === 'advance') {
29	    if (s.st === 'waiting' && !s.advanced) advance(s, ctx);
30	  } else if (input.op === 'action') {
31	    obligations = action(s, input, ctx);
32	  } else if (input.op === 'stop') {
33	    if (s.st === 'pending' || s.st === 'waiting' || s.st === 'overdue') {
34	      s.st = 'stopped';
35	      obligations = { cancel: ['deadline'] };
36	    }
37	  }
38	  return { output: outOf(s), state: s, obligations };
39	}
