1	// Parent orchestrator (DECOMPOSITION 3): routing, the phases of an order, the order of each tick. Owns SPEC-E 1
2	// (routing, subject, delivery order), 3.2, 3.5, the 4 preamble, R7.1, S5, S8-S13, S15. It emits no effects itself:
3	// every system is reached through a module.
4	//
5	// Phases: intake (placed, not yet recorded) -> fraud (recorded, not cleared) -> waiting (customer deadline, R3)
6	// -> processing (ready, R4) -> ended. A customer action in intake is held until the order is recorded (SPEC-E
7	// section 8, open point; this is the reading chosen here).
8	
9	const MIN = 60000;
10	const ENDED_STATUSES = ['completed', 'failed', 'cancelled', 'timedOut'];
11	
12	export function tick(input, ctx) {
13	  const events = Array.isArray(input.events) ? input.events : [];
14	  const self = input.instance;
15	  let st = input.state ?? null;
16	  let migrated = null;
17	
18	  // First tick of an instance started by an inbound message (SPEC-E 1 Routing, 3.5).
19	  if (st === null) {
20	    const first = events[0];
21	    const kind = first ? kindOf(first) : 'other';
22	    if (kind === 'placed') {
23	      const oid = normalise(ctx, first.payload?.orderId);
24	      if (!oid) return { decisions: { subject: null }, close: true };
25	      const other = openOther(ctx, oid, self);
26	      if (other) return { decisions: { subject: oid }, merge: { into: other } };
27	      if (ctx.query('orders.orders', { where: { orderId: oid }, limit: 1 }).length > 0) {
28	        return { decisions: { subject: oid }, close: true };
29	      }
30	      st = newState(oid, first.at);
31	    } else if (kind === 'action') {
32	      const oid = normalise(ctx, first.payload?.orderRef);
33	      const other = oid ? openOther(ctx, oid, self) : null;
34	      if (other) return { decisions: { subject: oid }, merge: { into: other } };
35	      return { decisions: { subject: oid }, close: true };
36	    } else if (kind === 'carrier') {
37	      const ref = first.payload?.fulfilmentRef;
38	      const rows = ref ? ctx.query('orders.fulfilments', { where: { fulfilmentId: ref }, limit: 1 }) : [];
39	      const oid = rows.length > 0 ? normalise(ctx, rows[0].orderId) : null;
40	      const other = oid ? openOther(ctx, oid, self) : null;
41	      if (other) return { decisions: { subject: oid }, merge: { into: other } };
42	      return { decisions: { subject: oid }, close: true };
43	    } else if (kind === 'migration') {
44	      const oid = normalise(ctx, first.payload?.orderId ?? first.payload?.order?.orderId);
45	      const rows = oid ? ctx.query('orders.orders', { where: { orderId: oid }, limit: 1 }) : [];
46	      if (rows.length === 0) return { decisions: { subject: oid }, close: true };
47	      st = newState(oid, rows[0].placedAt);
48	      migrated = rows[0];
49	    } else {
50	      return { decisions: { subject: null }, close: true };
51	    }
52	  }
53	
54	  // Every call to a module goes through here: its busy flag is kept and its output drives the phase.
55	  function call(mod, key, inp) {
56	    const o = ctx.call(mod, key, inp);
57	    st.busy[`${mod}/${key}`] = !!(o && o.busy);
58	    onOutput(mod, key, o);
59	    return o;
60	  }
61	
62	  function deliver(ev) {
63	    const owner = ctx.ownerOf(ev);
64	    if (!owner) return;
65	    const o = ctx.deliver(ev);
66	    st.busy[`${owner.module}/${owner.key}`] = !!(o && o.busy);
67	    onOutput(owner.module, owner.key, o);
68	  }
69	
70	  function onOutput(mod, key, o) {
71	    if (!o) return;
72	    if (mod === 'intake') {
73	      if (o.status === 'recorded' && !o.duplicate && st.phase === 'intake') recordOrder(o);
74	    } else if (mod === 'fraud') {
75	      if (st.phase !== 'fraud') return;
76	      if (o.state === 'cleared') clearing(o.at);
77	      else if (o.state === 'cancel') cancelOrder(o.reason, o.at);
78	    } else if (mod === 'customer-action') {
79	      if (st.phase === 'ended') return;
80	      if (o.state === 'ready' && st.phase === 'waiting') toProcessing(o.at);
81	      else if (o.state === 'cancel') cancelOrder(o.reason, o.at);
82	      else if (o.state === 'timedOut') setEnded();
83	    } else if (mod === 'fulfilment') {
84	      const sg = st.sagas[key];
85	      if (!sg) return;
86	      sg.end = o.end ?? null;
87	      sg.failing = !!o.failing;
88	      if ((o.end === 'completed' || o.end === 'failed') && !sg.told) {
89	        sg.told = true;
90	        call('order-progress', st.orderId, { op: 'ended', fulfilmentId: key, end: o.end, at: o.endedAt });
91	      }
92	    } else if (mod === 'order-progress') {
93	      if (o.state === 'ended') setEnded();
94	    } else if (mod === 'cancellation') {
95	      if (o.verdict === 'counts') setEnded();
96	    }
97	  }
98	
99	  // R1.1 / R1.4: the order is recorded; statuses, notices, the customer clock and the fraud check start.
100	  function recordOrder(o) {
101	    st.recorded = true;
102	    st.customerId = o.customerId;
103	    st.currency = o.currency;
104	    st.placedAt = o.placedAt;
105	    st.edition = o.edition;
106	    st.fulfilments = o.fulfilments.map(f => ({ fulfilmentId: f.fulfilmentId, location: f.location, available: f.available, items: f.items, amountMinor: f.amountMinor }));
107	    st.hasUnavailable = st.fulfilments.some(f => !f.available);
108	    st.phase = 'fraud';
109	    call('statuses', st.orderId, { op: 'init', fulfilments: st.fulfilments.map(f => ({ fulfilmentId: f.fulfilmentId, location: f.location })) });
110	    call('notices', st.orderId, { op: 'init', customerId: st.customerId });
111	    if (st.hasUnavailable) call('customer-action', st.orderId, { op: 'start', placedAt: st.placedAt, edition: st.edition, fulfilments: availability() });
112	    call('fraud', st.orderId, { op: 'start', placedAt: st.placedAt, edition: st.edition });
113	    const held = st.held;
114	    st.held = [];
115	    for (const a of held) routeAction(a);
116	  }
117	
118	  // R2.1 / R3.1: the order is cleared at c. Without unavailable items it is ready at once (R4.1).
119	  function clearing(c) {
120	    st.clearedAt = c;
121	    if (!st.hasUnavailable) return toProcessing(c);
122	    const o = call('customer-action', st.orderId, { op: 'cleared', at: c });
123	    if (o.state === 'waiting') st.phase = 'waiting';
124	    else if (o.state === 'ready') toProcessing(c);
125	  }
126	
127	  function toProcessing(at) {
128	    if (st.phase !== 'waiting' && st.phase !== 'fraud') return;
129	    st.phase = 'processing';
130	    st.readyAt = at;
131	  }
132	
133	  // A cancel that counts, or a fraud / timeout decision: the order is decided (S15). Fraud and the customer clock stop.
134	  function cancelOrder(reason, at) {
135	    if (st.phase === 'ended') return;
136	    call('cancellation', st.orderId, { op: 'cancel-order', at, reason, customerId: st.customerId });
137	    setEnded();
138	  }
139	
140	  function setEnded() {
141	    if (st.phase === 'ended') return;
142	    st.phase = 'ended';
143	    call('fraud', st.orderId, { op: 'stop' });
144	    if (st.hasUnavailable) call('customer-action', st.orderId, { op: 'stop' });
145	  }
146	
147	  // Customer actions by phase (SPEC-E 3.2, R3.2, R6.2-R6.4, S5, S8, S11, S15).
148	  function routeAction(a) {
149	    if (st.phase === 'ended') return;
150	    if (st.phase === 'intake') { st.held.push(a); return; }
151	    if (a.action === 'cancel') {
152	      if (st.phase === 'fraud') {
153	        call('cancellation', st.orderId, { op: 'customer-cancel', at: a.at, eventId: a.id, phase: 'not-cleared', customerId: st.customerId });
154	      } else if (st.phase === 'waiting') {
155	        call('customer-action', st.orderId, { op: 'action', action: 'cancel', at: a.at });
156	      } else if (st.phase === 'processing') {
157	        call('cancellation', st.orderId, { op: 'customer-cancel', at: a.at, eventId: a.id, phase: 'processing', customerId: st.customerId });
158	      }
159	    } else if (a.action === 'amend') {
160	      if ((st.phase === 'fraud' && st.hasUnavailable) || st.phase === 'waiting') {
161	        call('customer-action', st.orderId, { op: 'action', action: 'amend', at: a.at });
162	      }
163	    }
164	  }
165	
166	  // 3.3: a carrier report for one of our shipments goes to its fulfilment saga.
167	  function routeCarrier(ev) {
168	    const fid = ev.payload?.fulfilmentRef;
169	    if (!fid || !st.sagas[fid]) return;
170	    call('fulfilment', fid, {
171	      op: 'carrier',
172	      message: { code: ev.payload.code, reportedAt: ev.payload.reportedAt, carrier: ev.payload.carrier ?? null, shipmentId: ev.payload.shipmentId ?? null },
173	      at: ev.at,
174	    });
175	  }
176	
177	  // End of tick: the only place where forward steps are emitted (S9, S10). Nothing once the order has ended.
178	  function endOfTick() {
179	    if (st.phase === 'waiting') {
180	      call('customer-action', st.orderId, { op: 'advance' });
181	      return;
182	    }
183	    if (st.phase !== 'processing') return;
184	    const avail = st.fulfilments.filter(f => f.available);
185	    if (!st.progress) {
186	      st.progress = true;
187	      call('order-progress', st.orderId, { op: 'ready', at: st.readyAt, fulfilments: availability() });
188	    }
189	    for (const f of avail) {
190	      if (st.phase !== 'processing') return;
191	      if (st.sagas[f.fulfilmentId]) continue;
192	      st.sagas[f.fulfilmentId] = { end: null, failing: false, told: false };
193	      call('fulfilment', f.fulfilmentId, {
194	        op: 'start', orderId: st.orderId, customerId: st.customerId, currency: st.currency, edition: st.edition,
195	        readyAt: st.readyAt,
196	        fulfilment: { fulfilmentId: f.fulfilmentId, location: f.location, items: f.items, amountMinor: f.amountMinor },
197	      });
198	    }
199	    for (const f of avail) {
200	      if (st.phase !== 'processing') return;
201	      const sg = st.sagas[f.fulfilmentId];
202	      if (!sg || sg.end) continue;
203	      call('fulfilment', f.fulfilmentId, { op: 'advance' });
204	    }
205	  }
206	
207	  function availability() {
208	    return st.fulfilments.map(f => ({ fulfilmentId: f.fulfilmentId, available: f.available }));
209	  }
210	
211	  // 3.5: a migrated order continues from where it stands (its records say the phase and the steps done).
212	  function resumeMigration(o) {
213	    const oid = st.orderId;
214	    const rows = ctx.query('orders.fulfilments', { where: { orderId: oid }, limit: 20 });
215	    st.recorded = true;
216	    st.customerId = o.customerId;
217	    st.currency = o.currency;
218	    st.placedAt = o.placedAt;
219	    st.edition = chooseEdition(ctx.files, o.placedAt);
220	    st.fulfilments = rows.map(r => {
221	      const location = r.location ?? null;
222	      return { fulfilmentId: r.fulfilmentId, location, available: location !== null && r.status !== 'unavailable', items: r.items ?? [], amountMinor: r.amountMinor ?? 0, status: r.status };
223	    });
224	    st.hasUnavailable = st.fulfilments.some(f => !f.available);
225	    call('statuses', oid, { op: 'init', orderStatus: o.status, fulfilments: st.fulfilments.map(f => ({ fulfilmentId: f.fulfilmentId, location: f.location, status: f.status })) });
226	    call('notices', oid, { op: 'init', customerId: st.customerId });
227	    if (st.hasUnavailable) {
228	      call('customer-action', oid, { op: 'start', placedAt: st.placedAt, edition: st.edition, fulfilments: availability(), resumed: o.status !== 'pending' });
229	    }
230	    if (o.status === 'pending') {
231	      st.phase = 'fraud';
232	      call('fraud', oid, { op: 'start', placedAt: st.placedAt, edition: st.edition });
233	    } else if (o.status === 'customerActionRequired') {
234	      st.phase = 'waiting';
235	      call('customer-action', oid, { op: 'cleared', at: st.placedAt });
236	    } else if (o.status === 'processing') {
237	      st.phase = 'processing';
238	      st.readyAt = st.placedAt;
239	      st.progress = true;
240	      call('order-progress', oid, { op: 'ready', at: st.readyAt, fulfilments: availability() });
241	      for (const f of st.fulfilments.filter(x => x.available)) {
242	        st.sagas[f.fulfilmentId] = { end: null, failing: false, told: false };
243	        const records = {
244	          reservations: ctx.query('inventory.reservations', { where: { fulfilmentId: f.fulfilmentId }, limit: 200 }),
245	          charge: ctx.query('billing.charges', { where: { fulfilmentId: f.fulfilmentId }, limit: 1 })[0] ?? null,
246	          shipment: ctx.query('carrier.shipments', { where: { fulfilmentId: f.fulfilmentId }, limit: 1 })[0] ?? null,
247	        };
248	        call('fulfilment', f.fulfilmentId, {
249	          op: 'resume', orderId: oid, customerId: st.customerId, currency: st.currency, edition: st.edition, readyAt: st.readyAt,
250	          status: f.status, records,
251	          fulfilment: { fulfilmentId: f.fulfilmentId, location: f.location, items: f.items, amountMinor: f.amountMinor },
252	        });
253	      }
254	    } else {
255	      st.phase = 'ended';
256	    }
257	  }
258	
259	  if (migrated !== null) resumeMigration(migrated);
260	
261	  for (const ev of events) {
262	    const k = kindOf(ev);
263	    if (k === 'owned') deliver(ev);
264	    else if (k === 'placed') { if (st.orderId) call('intake', st.orderId, { op: 'placed', order: placedOrder(ev) }); }
265	    else if (k === 'action') routeAction({ action: ev.payload?.action, at: ev.at, id: ev.id });
266	    else if (k === 'carrier') routeCarrier(ev);
267	  }
268	
269	  if (st.phase !== 'ended') endOfTick();
270	
271	  const out = { decisions: { subject: st.orderId ?? null }, state: st };
272	  if (st.phase === 'ended' && !Object.values(st.busy).some(Boolean)) out.close = true;
273	  return out;
274	
275	  function placedOrder(ev) {
276	    return {
277	      orderId: st.orderId,
278	      customerId: ev.payload?.customerId,
279	      placedAt: ev.at,
280	      currency: ev.payload?.currency ?? 'EUR',
281	      items: ev.payload?.items,
282	    };
283	  }
284	}
285	
286	function newState(oid, at) {
287	  return {
288	    phase: 'intake', orderId: oid, placedAt: at ?? null, customerId: null, currency: null, edition: null,
289	    recorded: false, hasUnavailable: false, fulfilments: [], clearedAt: null, readyAt: null,
290	    held: [], progress: false, sagas: {}, busy: {},
291	  };
292	}
293	
294	function kindOf(ev) {
295	  const t = String(ev.type ?? '');
296	  const src = String(ev.source ?? '');
297	  if (t === 'migration') return 'migration';
298	  if (t === 'effect.result' || t === 'timer.fired' || t.startsWith('humanTask.')) return 'owned';
299	  if (t === 'order.placed' || src === 'shop') return 'placed';
300	  if (t === 'customer.action' || src === 'customer-portal') return 'action';
301	  if (t === 'carrier.status' || src === 'carrier') return 'carrier';
302	  return 'other';
303	}
304	
305	function normalise(ctx, raw) {
306	  if (raw === undefined || raw === null) return null;
307	  return ctx.call('order-id', 'n', { raw: String(raw) }).orderId;
308	}
309	
310	// The other open instance that declared this order as its subject (SPEC-E 1 Routing), if any.
311	function openOther(ctx, oid, self) {
312	  if (!oid) return null;
313	  for (const x of ctx.instances({ subject: oid }) ?? []) {
314	    const id = typeof x === 'string' ? x : x?.instance;
315	    if (id && id !== self) return id;
316	  }
317	  return null;
318	}
319	
320	// R1.3 (the parent needs it to resume a migrated order): the published edition in force at the date of `at`.
321	function chooseEdition(files, at) {
322	  const day = amsDate(at);
323	  let best = null;
324	  let bestFrom = '';
325	  for (const k of Object.keys(files ?? {})) {
326	    const m = /^rulebook\/([^/]+)\/edition\.json$/.exec(k);
327	    if (!m) continue;
328	    const v = files[k];
329	    const e = typeof v === 'string' ? JSON.parse(v) : v;
330	    const from = String(e?.effectiveFrom ?? '').slice(0, 10);
331	    if (from <= day && from >= bestFrom) { best = m[1]; bestFrom = from; }
332	  }
333	  if (best === null) throw new Error(`no edition in force at ${at}`);
334	  return best;
335	}
336	
337	function amsDate(iso) {
338	  const t = Date.parse(iso);
339	  const y = new Date(t).getUTCFullYear();
340	  const lastSunday = mo => { const d = new Date(Date.UTC(y, mo + 1, 0)); return d.getUTCDate() - d.getUTCDay(); };
341	  const off = t >= Date.UTC(y, 2, lastSunday(2), 1) && t < Date.UTC(y, 9, lastSunday(9), 1) ? 120 : 60;
342	  return new Date(t + off * MIN).toISOString().slice(0, 10);
343	}
